    // Outline vertices as (latitude, longitude), inverted from the site's map projection.
    static let latLon: [(Double, Double)] = {
        let numbers = path
            .replacingOccurrences(of: "M", with: " ")
            .replacingOccurrences(of: "L", with: " ")
            .replacingOccurrences(of: "Z", with: " ")
            .split(whereSeparator: { $0 == " " })
            .compactMap { Double($0) }
        var result: [(Double, Double)] = []
        var i = 0
        while i + 1 < numbers.count {
            let x = numbers[i], y = numbers[i + 1]
            let lon = minLon + (x / viewBoxWidth) * (maxLon - minLon)
            let lat = maxLat - (y / viewBoxHeight) * (maxLat - minLat)
            result.append((lat, lon))
            i += 2
        }
        return result
    }()
